#include <bits/stdc++.h>
using namespace std;
using K=uint64_t;
K key(int x,int y){return(uint64_t(uint32_t(x))<<32)|uint32_t(y);}
pair<int,int> rot(int x,int y,int h){if(!h)return{x,y};if(h==1)return{y,-x};if(h==2)return{-x,-y};return{-y,x};}
struct C{int x,y,first,last;};struct M{string word;vector<C>raw,tar;int dx,dy,dh;};vector<M>ms;using S=bitset<256>;vector<array<S,7>>TR;S INITIAL;unordered_map<K,int>field;int DEP=12,best=0;uint64_t cap=10000000,nodes=0;bool stopped=false;string path,bestpath;const string names="DCVUFQB";int dx[4]={0,1,0,-1},dy[4]={1,0,-1,0};
vector<C> geo(string w,int &x,int &y,int &h){map<pair<int,int>,pair<int,int>>r;vector<pair<int,int>>order;x=y=h=0;for(char c:w){int v=c=='L';pair<int,int>p={x,y};if(!r.count(p)){r[p]={v,v};order.push_back(p);}else{assert(r[p].second!=v);r[p].second=v;}h=(h+(v?3:1))%4;x+=dx[h];y+=dy[h];}vector<C>out;for(auto p:order)out.push_back({p.first,p.second,r[p].first,r[p].second});return out;}
void dfs(int x,int y,int h,int fuel,int zero,S states){if(++nodes>cap){stopped=true;return;}if(path.size()==DEP)return;for(int a=0;a<(int)ms.size();a++){S ns;for(int u=0;u<(int)TR.size();u++)if(states[u])ns|=TR[u][a];if(ns.none())continue;auto&m=ms[a];bool ok=true;for(auto c:m.tar){auto[u,v]=rot(c.x,c.y,h);auto it=field.find(key(x+u,y+v));if(it!=field.end()&&it->second==c.first){ok=false;break;}}if(!ok)continue;int f=fuel;vector<pair<K,int>>undo;for(auto c:m.raw){auto[u,v]=rot(c.x,c.y,h);K p=key(x+u,y+v);auto it=field.find(p);int old=it==field.end()?-1:it->second;if(old<0&&c.first==1)f++;undo.push_back({p,old});field[p]=c.last;}path+=names[a];int z=f==fuel?zero+1:0;if(z>best){best=z;bestpath=path;cout<<"MAXZERO "<<best<<" fuel "<<f<<" word "<<path<<" nodes "<<nodes<<endl;}auto[u,v]=rot(m.dx,m.dy,h);dfs(x+u,y+v,(h+m.dh)%4,f,z,ns);path.pop_back();for(auto it=undo.rbegin();it!=undo.rend();it++){if(it->second<0)field.erase(it->first);else field[it->first]=it->second;}if(stopped)return;}}
int main(int argc,char**argv){if(argc>1)DEP=stoi(argv[1]);if(argc>2)cap=stoull(argv[2]);string w;for(int i=0;i<7;i++){cin>>w;M m;m.word=w;m.raw=geo(w,m.dx,m.dy,m.dh);int x,y,h;m.tar=geo(w+"LLLLRLRRRRL",x,y,h);ms.push_back(m);}int nv,ne;cin>>nv>>ne;assert(nv<=256);TR.resize(nv);while(ne--){int u,a,v;cin>>u>>a>>v;TR[u][a][v]=1;INITIAL[u]=1;}field.reserve(2000);dfs(0,0,0,0,0,INITIAL);cout<<"DONE nodes "<<nodes<<" complete "<<!stopped<<" depth "<<DEP<<" maxzero "<<best<<" word "<<bestpath<<endl;}
